    @Override
    public void execute(GatewayContext context, Map<String, String> extendInfo) {
        //请求头信息
        HttpHeaders httpHeaders = getHeader(context);

        //头信息中添加参数
        addHeaderParameters(httpHeaders, context, extendInfo);

        //请求方法
        HttpMethod httpMethod = getMethod(context);

        //是否在url上添加参数
        boolean isAddParametersToUrl = isAddParametersToUrl(httpMethod, context);

        //请求实体
        HttpEntity httpEntity = getHttpEntity(httpHeaders, httpMethod, context, isAddParametersToUrl, extendInfo);

        //请求路由
        RoutingVO routingVO = getRoutingVO(context, httpMethod);

        //请求地址
        URI uri = getUri(context, routingVO.getAddress(), isAddParametersToUrl);

        //请求结果
        HttpResult result = HttpUtil.send(uri, getRestTemplate(), httpMethod, getResultType(), httpEntity, context.getCloseRequestLog(), context.getCloseResponseLog());

        //结果状态转换
        resultStatusConvert(result, context, extendInfo);

        context.setResult(result);
    }

    //路由配置
    protected RoutingVO getRoutingVO(GatewayContext context, HttpMethod httpMethod) {
        //请求路由
        RoutingVO routingVO = context.getAppService().getRoutingMap().get(httpMethod.name());
        if (routingVO == null) {
            throw new GatewayNewException(ResultCodeEnum.INNER_ERROR, "缺少路由配置:" + httpMethod.name());
        }
        return routingVO;
    }

    /**
     * 获取请求地址
     *
     * @param context
     * @param address
     * @param isAddParametersToUrl
     * @return
