            return uriComponentsBuilder.build().toUri();

        }

        //设置url参数
        if (isAddParametersToUrl) {
            context.getRequestParam().forEach((key, value) -> uriComponentsBuilder.queryParam(key, value != null ? value : ""));
        }

        return uriComponentsBuilder.build().toUri();
    }

    /**
