     * @param context
     * @param extendInfo
     */
    protected void addHeaderParameters(HttpHeaders httpHeaders, GatewayContext context, Map<String, String> extendInfo){
        //头信息中添加参数
        if (extendInfo == null || !extendInfo.containsKey(AppServiceConstants.NO_SET_GATEWAY_PARAMETERS)) {
            GatewayContextUtil
                    .appMap(context)
                    .forEach((key, value) -> httpHeaders.set(key, value));
        }
    }

    /**
     * 是否添加参数曹url上
     * @param httpMethod
     * @param context
     * @return
     */
    protected boolean isAddParametersToUrl(HttpMethod httpMethod, GatewayContext context){
        if(HttpMethod.GET == httpMethod){
            return true;
        }

