import cn.com.cathayins.wireless.eclipse.gateway.common.utils.ResultUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestTemplate;

import java.net.URI;

/**
 * @author 致远
 * @date 2022/5/2 20:26
 */

@Component
@Slf4j
public class HttpUtil {

    /**
     * 发送
     *
     * @param uri
     * @param restTemplate
     * @param method
     * @param type
     * @param httpEntity
     * @param <T>
     * @return
     */
    public static <T> HttpResult send(URI uri, RestTemplate restTemplate, HttpMethod method, Class<T> type, HttpEntity<?> httpEntity) {
        //响应结果
        ResponseEntity<T> response;
        try {
            response = ResultUtils.call(() -> restTemplate.exchange(uri, method, httpEntity, type)
                    , () -> MessageFormatter.format("请求地址：【{}】 报文【{}】", uri.toString(), httpEntity.getBody()).getMessage());
        } catch (GatewayNewException e) {
            return HttpResult.ofFailed(e.getErrorEnum());
        }

        if (response.getStatusCode() != HttpStatus.OK) {
            return HttpResult.ofFailed(ResultCodeEnum.OUTSIDE_REMOTE_ERROR, response.getStatusCodeValue(), response.getBody());
        }

        return HttpResult.ofSuccess(response.getBody());
    }

